#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_new_with_string_length_successful_allocation(void) {
    // Setup: create a string to use as buffer data
    char test_str[] = "hello world";
    size_t test_len = 5; // Only use "hello"

    // Test: call buffer_new_with_string_length
    buffer_t *buf = buffer_new_with_string_length(test_str, test_len);

    // Assertions
    TEST_ASSERT_NOT_NULL(buf);
    TEST_ASSERT_EQUAL(test_len, buf->len);
    TEST_ASSERT_EQUAL_PTR(test_str, buf->data);
    TEST_ASSERT_EQUAL_PTR(test_str, buf->alloc);

    // The buffer does not copy the string, so the data should match the first 'test_len' bytes
    // We can check that the buffer's data points to the original string and the content matches
    TEST_ASSERT_EQUAL_MEMORY(test_str, buf->data, test_len);

    // Cleanup: free the buffer (does not free test_str)
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_new_with_string_length_successful_allocation);
    return UNITY_END();
}

